from dataclasses import dataclass
from typing import Any,overload
class HashableList(list):
 __hash__=object.__hash__
class NonData:
 @overload
 def __get__(self,obj:None,owner:Any)->list['NonData']:...
 @overload
 def __get__(self,obj:object,owner:Any)->'NonData':...
 def __get__(self,obj,owner):return HashableList([self]) if obj is None else self
